values (md5('PE-007:policy:arrival:8')::uuid, 'PE-007', 'https://jumbaloo.com/ridgeway/faqs-ridgeway/', '2026-11-07', 'verified', null, 'arrival', 'Playtime can''t be extended if you arrive late, because the facility runs on a set schedule.', 8);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-007:policy:arrival:9')::uuid, 'PE-007', 'https://jumbaloo.com/ridgeway/faqs-ridgeway/', '2026-11-07', 'verified', null, 'arrival', 'Everyone gets a wristband at admission and must wear it in the play area. Every adult pays, and older children who aren''t playing still pay.', 9);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-007:policy:arrival:10')::uuid, 'PE-007', 'https://jumbaloo.com/ridgeway/faqs-ridgeway/', '2026-11-07', 'verified', null, 'arrival', 'Strollers can come as far as the front lobby, not into the play area.', 10);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-007:policy:food_rule:11')::uuid, 'PE-007', 'https://jumbaloo.com/policy/', '2026-11-07', 'verified', 'The Ridgeway FAQ lists only baby bottles and baby food as exceptions.', 'food_rule', 'No outside food or drinks, except baby bottles, baby food and fresh fruit and vegetables. No food, drinks, candy or gum in the playground.', 11);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-007:policy:food_rule:12')::uuid, 'PE-007', 'https://jumbaloo.com/ridgeway/faqs-ridgeway/', '2026-11-07', 'verified', null, 'food_rule', 'There''s no water fountain; you can bring your own water bottle or buy water at the snack counter.', 12);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-007:policy:hours_note:13')::uuid, 'PE-007', 'https://jumbaloo.com/contact-us/', '2026-11-07', 'verified', 'The contact page and footer say Monday to Friday 12–8 pm and Saturday–Sunday 10 am–8 pm; the home page and playtime page say Monday to Friday 10 am–8 pm and Saturday–Sunday 9 am–8 pm.', 'hours_note', 'Weekdays 12–8 pm and weekends 10 am–8 pm per the contact page; call to confirm opening times before you go.', 13);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-007:policy:other:14')::uuid, 'PE-007', 'https://jumbaloo.com/ridgeway/', '2026-11-07', 'verified', null, 'other', 'The Ridgeway pages show a "Coming Soon" banner and a renovation pop-up ("Getting a Glow-Up!") without saying what''s affected; check before you go.', 14);
